  FT["PH-H6561"] = {"id":"PH-H6561","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8082_1995.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 Sulu-Tawi-Tawi 广播基金会在苏禄与 Tawi-Tawi 省建设、运营和维护广播与电视站并为其他目的特许经营权法案","en":"An Act Granting a Franchise to Sulu-tawi-tawi Broadcasting Foundation, Inc., to Construct, Operate and Maintain Stations for Radio and Television in the Provinces of Sulu and Tawi-tawi, and for Other Purposes","orig":"An Act Granting a Franchise to Sulu-tawi-tawi Broadcasting Foundation, Inc., to Construct, Operate and Maintain Stations for Radio and Television in the Provinces of Sulu and Tawi-tawi, and for Other Purposes","vi":"Đạo luật cấp quyền khai thác cho Sulu-tawi-tawi Broadcasting Foundation, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại tỉnh Sulu và Tawi-tawi","th":"พระราชบัญญัติให้สัมปทานแก่ Sulu-tawi-tawi Broadcasting Foundation, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในจังหวัด Sulu และ Tawi-tawi","id":"Undang-Undang memberikan waralaba kepada Sulu-tawi-tawi Broadcasting Foundation, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Provinsi Sulu dan Tawi-tawi","ms":"Akta memberikan francais kepada Sulu-tawi-tawi Broadcasting Foundation, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Wilayah Sulu dan Tawi-tawi"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8082","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-07-06","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8082_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6561-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Sulu-Tawi-Tawi Broadcasting Foundation, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations in the provinces of Sulu and Tawi-Tawi, at such places as the grantee may select and the National Telecommunications Commission may approve with the corresponding technological auxiliaries or facilities, special broadcast, other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6561-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon and should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6561-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permit and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6561-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6561-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the station of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6561-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6561-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6561-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax at such percentage as may be prescribed by law on all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6561-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act, scene or other matter to be broadcast and/or telecast from its stations: Provided, That the grantee, during any broadcast and/or telecast shall cut off from the air the speech, play, act, scene or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6561-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6561-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest of the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6561-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with a general broadcast policy law which the Congress of the Philippines may hereafter enact."}},{"id":"PH-H6561-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6561-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6561-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its approval."}}],"pack":"ph-p93","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting a Franchise to Sulu-tawi-tawi Broadcasting Foundation, Inc., to Construct, Operate and Maintain Stations for Radio and Television in the Provinces of Sulu and Tawi-tawi, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6562"] = {"id":"PH-H6562","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8083_1995.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Radio Audience Developers 综合组织在菲律宾建设、安装、设立、运营和维护商业广播站的特许经营权法案","en":"An Act Granting the Radio Audience Developers Integrated Organization, Inc., a Franchise to Construct, Install, Establish, Operate and Maintain Commercial Radio Stations in the Philippines","orig":"An Act Granting the Radio Audience Developers Integrated Organization, Inc., a Franchise to Construct, Install, Establish, Operate and Maintain Commercial Radio Stations in the Philippines","vi":"Đạo luật cấp quyền khai thác cho Radio Audience Developers Integrated Organization, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Radio Audience Developers Integrated Organization, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Radio Audience Developers Integrated Organization, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Filipina","ms":"Akta memberikan francais kepada Radio Audience Developers Integrated Organization, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Filipina"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 8083","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-07-06","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8083_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6562-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Radio Audience Developers Integrated Organization, Inc., its successors or assigns and hereinafter referred to as the grantee, a franchise to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio broadcasting stations at such places in the Philippines as the grantee may select and the National Telecommunications Commission may approve, with the corresponding technological auxiliaries or facilities, special broadcast and other broadcast program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6562-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon and should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6562-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and facilities and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6562-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations or facilities for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest; or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6562-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations or facilities of the grantee, temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when they shall be so operated."}},{"id":"PH-H6562-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of the effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6562-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6562-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax at such percentage as may be prescribed by law on all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code, and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6562-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act, scene or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast shall cut off from the air the speech, play, act, scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6562-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6562-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred, or assigned shall be subject to all the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6562-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6562-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6562-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H6562-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirements. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of its franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H6562-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p93","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Radio Audience Developers Integrated Organization, Inc., a Franchise to Construct, Install, Establish, Operate and Maintain Commercial Radio Stations in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6563"] = {"id":"PH-H6563","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8084_1995.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 Raven 广播公司在吕宋及菲律宾其他频率仍可用地区建设、维护和运营广播电视站的特许经营权法案","en":"An Act Granting Raven Broadcasting Corporation a Franchise to Construct, Maintain and Operate Radio and Television Broadcasting Stations Within Luzon and Other Areas in the Philippines Where Frequencies And/Or Channels Are Still Available for Radio and Television Broadcasting","orig":"An Act Granting Raven Broadcasting Corporation a Franchise to Construct, Maintain and Operate Radio and Television Broadcasting Stations Within Luzon and Other Areas in the Philippines Where Frequencies And/Or Channels Are Still Available for Radio and Television Broadcasting","vi":"Đạo luật cấp quyền khai thác cho Raven Broadcasting Corporation để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Raven Broadcasting Corporation เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Raven Broadcasting Corporation untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Raven Broadcasting Corporation untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8084","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-07-06","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8084_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6563-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Raven Broadcasting Corporation, hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio and/or television broadcasting stations within Luzon Island and other areas in the Philippines where frequencies and/or channels are still available for radio and television broadcasting, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6563-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon and should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6563-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permit and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6563-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act, scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6563-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the station of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6563-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6563-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6563-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6563-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act, scene or other matter to be broadcast and/or telecast from its stations: Provided, That the grantee, during any broadcast and telecast shall cut off from the air the speech, play, act, scene or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6563-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6563-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest of the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6563-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H6563-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6563-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6563-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its approval."}}],"pack":"ph-p93","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Raven Broadcasting Corporation a Franchise to Construct, Maintain and Operate Radio and Television Broadcasting Stations Within Luzon and Other Areas in the Philippines Where Frequencies And/Or Channels Are Still Available for Radio and Television Broadcasting","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6564"] = {"id":"PH-H6564","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8085_1995.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 Mount Apo 科学基金会学校在棉兰老岛设立、维护和运营广播电视站的特许经营权法案","en":"An Act Granting the Mount Apo Science Foundation School, Inc., a Franchise to Establish, Maintain and Operate Radio and Television Broadcasting Stations in the Island of Mindanao","orig":"An Act Granting the Mount Apo Science Foundation School, Inc., a Franchise to Establish, Maintain and Operate Radio and Television Broadcasting Stations in the Island of Mindanao","vi":"Đạo luật cấp quyền khai thác cho Mount Apo Science Foundation School, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Mount Apo Science Foundation School, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Mount Apo Science Foundation School, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Mount Apo Science Foundation School, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment","education"],"docNumber":"Republic Act No. 8085","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-07-06","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8085_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6564-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Mount Apo Science Foundation Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations in the island of Mindanao with the corresponding technological auxiliaries or facilities, special broadcast and other program, distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6564-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6564-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permit and licenses for its stations and shall not use any frequency in they radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6564-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6564-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the station of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6564-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6564-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - This franchise shall become effective upon acceptance in writing by the grantee. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6564-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax at such percentage as may be prescribed by law on all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with, and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6564-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act, scene or other matter to be broadcast and/or telecast from its stations: Provided, That the grantee, during any broadcast and telecast shall cut off from the air the speech, play, act, scene or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6564-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6564-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest of the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6564-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H6564-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6564-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6564-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its approval."}}],"pack":"ph-p93","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Mount Apo Science Foundation School, Inc., a Franchise to Establish, Maintain and Operate Radio and Television Broadcasting Stations in the Island of Mindanao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
